<script setup>
import {branchesApi} from '../../api/branches.api'
import {useApiState} from '../../composables/useApiState'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
const list=useApiState(),detail=useApiState()
const map=branch=>branch.location?.latitude!=null&&branch.location?.longitude!=null?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(branch.location.latitude+','+branch.location.longitude):null
function load(){return list.run(()=>branchesApi.publicList())}load()
</script>
<template><main id="main" class="container section-space"><div class="section-heading"><h1>فروع شيشلي</h1><RouterLink class="text-button" to="/menu">اختيار فرع للطلب</RouterLink></div><ApiFeedback variant="cards" :loading="list.loading.value" :error="list.error.value" @retry="load"/><div class="offers-grid"><article v-for="branch in list.data.value||[]" :key="branch.id" class="checkout-panel"><h2>{{ branch.name }}</h2><p>{{ branch.location?.city }}، {{ branch.location?.district }}</p><p>{{ branch.location?.address }}</p><a v-if="branch.phone" :href="'tel:'+branch.phone"><bdi>{{ branch.phone }}</bdi></a><p>{{ branch.supports_pickup?'استلام من الفرع':'' }} {{ branch.supports_delivery?'· توصيل':'' }}</p><a v-if="map(branch)" class="text-button" :href="map(branch)" target="_blank" rel="noopener noreferrer">الموقع على الخريطة</a><button class="text-button" :disabled="detail.loading.value" @click="detail.run(()=>branchesApi.publicShow(branch.id))">تفاصيل الفرع</button></article></div><p v-if="list.data.value&&!list.data.value.length" class="empty-search">لا توجد فروع متاحة.</p><ApiFeedback variant="detail" :loading="detail.loading.value" :error="detail.error.value" @retry="detail.clear"/><section v-if="detail.data.value" class="checkout-panel"><h2>{{ detail.data.value.name }}</h2><p>{{ detail.data.value.location?.address }}</p><p>{{ detail.data.value.accepts_orders?'استقبال الطلبات مفعّل؛ يُراجع التوفر حسب ساعات العمل عند اختيار الفرع.':'استقبال الطلبات متوقف.' }}</p><p v-if="detail.data.value.whatsapp"><a :href="'https://wa.me/'+detail.data.value.whatsapp.replace(/\D/g,'')" target="_blank" rel="noopener noreferrer">واتساب الفرع</a></p></section></main></template>
